 var
  arr: array [0..5] of integer = (8, 1, 6, 3, 4, 15);
  i: integer;
  aduk: array [0..6] of integer;

procedure kalikali();
begin
  aduk[0] := 1;
  for i := 1 to 6 do
    aduk[i] := aduk[i-1] * arr[i-1];
end;

function hasil(kiri, kanan: integer): integer;
begin
  hasil := (aduk[kanan] div aduk[kiri-1]);
end;

begin
  kalikali();
  writeln(aduk[3]);
  writeln(hasil(2,3));
  writeln(hasil(4,6));
end.

